/* PHONE-4\uFF1A\u6316\u77FF\u63D0\u9192\uFF1D\u5F15\u64CE\u7684 data/mine_alerts.json\uFF08[{ at, id, name, liqUsd, text }]\uFF09\uFF0C\u7535\u8111\u653E\u5728 ST.mineAlerts\u3002\u8BBE\u5B9A\u9875\u6709\u5361\u7247\uFF1B\u8FD9\u6B21\u6253\u5F00\u4E4B\u540E\u7684\u65B0\u63D0\u9192\u4E5F\u8DF3\u63D0\u793A */
