const PXS={sync:10e3};/* \u6280\u672F\u7528\uFF1A\u591A\u4E45\u8DDF\u7535\u8111\u5BF9\u4E00\u6B21\u81EA\u9009 */
let PQ=[];try{const o=JSON.parse(localStorage.getItem('pxWQ')||'[]');if(Array.isArray(o))PQ=o}catch{}
if(!localStorage.getItem('pxWMig')){for(const x of W)PQ.push({op:'add',c:x.c,net:x.net,sym:x.sym||''});try{localStorage.setItem('pxWMig','1')}catch{}}/* \u4EE5\u524D\u53EA\u5B58\u5728\u624B\u673A\u7684\u81EA\u9009\uFF0C\u7B2C\u4E00\u6B21\u8FDE\u4E0A\u8865\u9001\u5230\u7535\u8111 */
